import data from '@/generated/curriculum.json';
import type { Curriculum, Level, Stage, World } from './schema';

export type { Curriculum, Level, Stage, World, Unit } from './schema';

/** Compiled curriculum (generated by `npm run content` from content/). */
export const curriculum = data as unknown as Curriculum;

export const worldById = new Map<string, World>(curriculum.worlds.map((w) => [w.id, w]));
export const stageById = new Map<string, Stage>(curriculum.stages.map((s) => [s.id, s]));
export const levelById = new Map<string, Level>(curriculum.levels.map((l) => [l.id, l]));

const byStage = new Map<string, Level[]>();
for (const s of curriculum.stages) byStage.set(s.id, s.units.flatMap((u) => u.levelIds.map((id) => levelById.get(id)!)));

export const levelsOfStage = (stageId: string): Level[] => byStage.get(stageId) ?? [];
export const levelsOfWorld = (worldId: string): Level[] => worldById.get(worldId)?.stageIds.flatMap(levelsOfStage) ?? [];

/** "World 1 · Stage 2" style coordinates for a stage. */
export const stageCode = (s: Stage) => `${worldById.get(s.worldId)!.order}-${s.order}`;
